// Form data extract karo
let masterSheetIdRaw = $input.first().json['Master Google Sheet ID or Full URL'] || '';
let masterSheetId = masterSheetIdRaw.trim();

// Auto-extract ID if full URL is pasted
if (masterSheetId.includes('/d/')) {
  masterSheetId = masterSheetId.split('/d/')[1].split('/')[0];
}

const city = $input.first().json['City / State'] || '';
const country = $input.first().json['Country'] || '';
const niche = $input.first().json['Niche / Industry'] || '';
const customQuestions = $input.first().json['Custom Questions / Query Guidelines'] || '';
const sourcesChoice = $input.first().json['Sources to Search'] || 'All Platforms (24h Filter)';

// Tab Name build karo (e.g., Real Estate - Houston)
const tabName = `${niche} - ${city}`.slice(0, 30); // Max 30 chars for tab safety

// Reddit search query build karo
const searchQuery = `${niche} ${city} ${country}`;
const redditQuery = encodeURIComponent(searchQuery);
const redditUrl = `https://www.reddit.com/search.rss?q=${redditQuery}&sort=new&t=day`;

// 24h Filtered Search URLs for platforms
const linkedin24hUrl = `https://www.google.com/search?q=site:linkedin.com/posts+${encodeURIComponent(`${niche} ${city} ${country}`)}&tbs=qdr:d`;
const reddit24hWebUrl = `https://www.reddit.com/search/?q=${encodeURIComponent(`${niche} ${city} ${country}`)}&t=day&sort=new`;
const googleMapsUrl = `https://www.google.com/maps/search/${encodeURIComponent(`${niche} ${city} ${country}`)}`;
const facebook24hUrl = `https://www.google.com/search?q=site:facebook.com+${encodeURIComponent(`${niche} ${city}`)}&tbs=qdr:d`;
const generalForums24hUrl = `https://www.google.com/search?q=${encodeURIComponent(`"${niche}" "${city}" ("help" OR "question" OR "looking for" OR "recommendation")`)}&tbs=qdr:d`;

// Custom questions parse karo
const questionsList = customQuestions
  .split('\n')
  .map(q => q.trim())
  .filter(q => q.length > 0);

const timestamp = new Date().toISOString();

return [
  {
    json: {
      masterSheetId,
      tabName,
      city,
      country,
      niche,
      customQuestions: questionsList,
      customQuestionsRaw: customQuestions,
      sourcesChoice,
      redditUrl,
      redditQuery: searchQuery,
      linkedin24hUrl,
      reddit24hWebUrl,
      googleMapsUrl,
      facebook24hUrl,
      generalForums24hUrl,
      timestamp
    }
  }
];

// Response parse karo
const inputData = $input.first().json || {};
const prevData = $('Build Search Data').first().json;
const sourceChoice = prevData.sourcesChoice || '';

let formattedPosts = [];

// Parse XML if Reddit was queried and returned content
if (sourceChoice.includes('Reddit') || sourceChoice.includes('All')) {
  let rawXml = '';
  if (typeof inputData === 'string') {
    rawXml = inputData;
  } else if (inputData.data) {
    rawXml = typeof inputData.data === 'string' ? inputData.data : JSON.stringify(inputData.data);
  } else {
    rawXml = JSON.stringify(inputData);
  }

  // Regex to extract <entry> items from RSS Feed
  const entryRegex = /<entry>[\s\S]*?<title>(.*?)<\/title>[\s\S]*?<link [^>]*href="(.*?)"[\s\S]*?<updated>(.*?)<\/updated>[\s\S]*?<\/entry>/gi;
  let match;
  let count = 0;

  while ((match = entryRegex.exec(rawXml)) !== null && count < 10) {
    count++;
    let title = match[1]
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&#39;/g, "'")
      .replace(/&quot;/g, '"');
    const url = match[2];
    const updated = match[3];
    const postDate = new Date(updated);
    const hoursAgo = Math.max(0, Math.round((Date.now() - postDate.getTime()) / (1000 * 60 * 60)));

    formattedPosts.push({
      index: count,
      title,
      url,
      postedTime: `${hoursAgo} hours ago`
    });
  }
}

// Summary for sheets
const topPostsSummary = formattedPosts.length > 0
  ? formattedPosts
      .map(p => `${p.index}. [${p.postedTime}] ${p.title}
   URL: ${p.url}`)
      .join('\n\n')
  : (sourceChoice.includes('Reddit') || sourceChoice.includes('All'))
      ? 'No direct Reddit posts found in last 24h. Use 24h Search Link below.'
      : 'N/A (Reddit not selected)';

// Custom questions as string
const questionsStr = prevData.customQuestions.length > 0
  ? prevData.customQuestions.map((q, i) => `Q${i+1}: ${q}`).join('\n')
  : 'No custom questions provided';

return [
  {
    json: {
      MasterSheetId: prevData.masterSheetId,
      TabName: prevData.tabName,
      Timestamp: prevData.timestamp,
      City: prevData.city,
      Country: prevData.country,
      Niche: prevData.niche,
      'Source Selected': sourceChoice,
      'Custom Questions': questionsStr,
      '24h Queries Found': formattedPosts.length,
      'Top Reddit Queries (Last 24h)': topPostsSummary,
      'Reddit (24h Search)': (sourceChoice.includes('Reddit') || sourceChoice.includes('All')) ? prevData.reddit24hWebUrl : 'N/A',
      'LinkedIn (24h Search)': (sourceChoice.includes('LinkedIn') || sourceChoice.includes('All')) ? prevData.linkedin24hUrl : 'N/A',
      'Facebook (24h Search)': (sourceChoice.includes('Facebook') || sourceChoice.includes('All')) ? prevData.facebook24hUrl : 'N/A',
      'General Forums (24h Search)': (sourceChoice.includes('Forums') || sourceChoice.includes('All')) ? prevData.generalForums24hUrl : 'N/A',
      'Google Maps URL': (sourceChoice.includes('Maps') || sourceChoice.includes('All')) ? prevData.googleMapsUrl : 'N/A'
    }
  }
];
